import { useNavigate } from 'react-router-dom';
import { Download, ArrowRight } from 'lucide-react';
import { downloadBytes } from '../../lib/pdfEngine.js';
import { setHandoffFiles } from '../../lib/fileHandoff.js';

const OPEN_TARGETS = [
  { slug: 'merge', label: 'Merge' },
  { slug: 'split', label: 'Split' },
  { slug: 'rotate', label: 'Rotate' },
  { slug: 'extract', label: 'Extract' },
  { slug: 'reorder', label: 'Reorder' },
];

/**
 * Actions for a freshly generated PDF: download it, or open it directly
 * inside another tool. The generated bytes are wrapped in a File and
 * passed through the in-memory handoff, so the target tool loads with
 * the file already in place — nothing is uploaded or re-picked.
 */
export default function GeneratedPdfActions({ bytes, filename, excludeSlug }) {
  const navigate = useNavigate();

  const openIn = (slug) => {
    const file = new File([bytes], filename, { type: 'application/pdf' });
    setHandoffFiles(slug, [file]);
    navigate(`/tools/${slug}`);
  };

  return (
    <div>
      <div className="flex flex-wrap gap-3">
        <button
          onClick={() => downloadBytes(bytes, filename)}
          className="inline-flex items-center justify-center gap-2 text-sm font-semibold bg-brand-600 text-white px-6 py-3 rounded-xl hover:bg-brand-700 active:scale-[0.98] shadow-md shadow-brand-600/25 transition-all touch-manipulation min-h-[48px]"
        >
          <Download className="w-4 h-4" />
          Download {filename}
        </button>
      </div>
      <p className="mt-4 mb-2 text-xs font-bold uppercase tracking-[0.16em] text-ink-soft">
        Or open it in a tool
      </p>
      <div className="flex flex-wrap gap-2">
        {OPEN_TARGETS.filter((t) => t.slug !== excludeSlug).map((t) => (
          <button
            key={t.slug}
            onClick={() => openIn(t.slug)}
            className="inline-flex items-center gap-1.5 text-sm font-semibold text-brand-700 bg-brand-50 border border-brand-200 rounded-full px-4 py-2.5 hover:bg-brand-100 transition-colors touch-manipulation min-h-[44px]"
          >
            Open in {t.label}
            <ArrowRight className="w-3.5 h-3.5" />
          </button>
        ))}
      </div>
    </div>
  );
}
